const fs = require('fs');
const vm = require('vm');
const path = require('path');
const root = path.resolve(__dirname, '..', '..');
const context = { console, Map, Set, Number, Object, Array, Error, TypeError, Promise };
context.window = context;
vm.createContext(context);
['engine/ecs/Entity.js','engine/ecs/Component.js','engine/ecs/System.js','engine/ecs/ECSWorld.js','engine/characters/CharacterTransformSystem.js','engine/characters/CharacterSystem.js'].forEach((file) => {
  vm.runInContext(fs.readFileSync(path.join(root, file), 'utf8'), context, { filename: file });
});
const ns = context.CiudadEngine;
const world = new ns.ECSWorld();
const transformSystem = new ns.CharacterTransformSystem();
world.addSystem(transformSystem);
const entity = world.createEntity('Test NPC');
const object = { position: { x: 0, y: 0, z: 0 }, rotation: { y: 0 } };
world.addComponent(entity, 'Transform', { x: 4, y: 2, z: -3, rotationY: 1.5 });
world.addComponent(entity, 'CharacterVisual', { object });
world.update(1 / 60, 1);
if (object.position.x !== 4 || object.position.y !== 2 || object.position.z !== -3 || object.rotation.y !== 1.5) throw new Error('Transform sync failed');
const animationSystem = new ns.CharacterSystem();
let updates = 0;
const mixer = { update(delta) { if (delta > 0) updates++; }, stopAllAction() {} };
animationSystem.register(entity, mixer, {});
world.addSystem(animationSystem);
world.update(1 / 60, 1);
if (updates !== 1) throw new Error('Animation mixer update failed');
world.removeEntity(entity);
world.update(1 / 60, 1);
if (animationSystem.mixers.size !== 0) throw new Error('Destroyed entity mixer cleanup failed');
console.log('CharacterSystem smoke test: PASS');
